mapper.select:
SELECT /* LGVATT20551.retrieveSwapHolidayRequest */ ATT_SO.SUBSIDIARY_CODE ,ATT_SO.EMPLOYEE_NO ,EM.FULL_NAME_LOCAL AS employee_Name ,EM.ORG_NAME_LOCAL AS organization_Name ,EM.organization_ID AS organization_ID ,ATT_SO.shift_type_code AS SHIFT_TYPE_CODE ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', ATT_SO.shift_type_code, NULL, 'en') AS FROM dual) AS SHIFT_TYPE_NAME ,ATT_SO.TIME_AND_ATTENDANCE_YYYYMM ,TO_CHAR(ATT_SO.WEEKLY_HOLIDAY, 'DD/MM/YYYY') AS WEEKLY_HOLIDAY ,ATT_SO.WEEKLY_HOLIDAY_SHIFT_TYPE_CODE ,(SELECT T.SHIFT_TYPE_CODE FROM TB_ATT_RESULT_N T WHERE T.SUBSIDIARY_CODE = ATT_SO.SUBSIDIARY_CODE AND T.TIME_AND_ATTENDANCE_DATE = ATT_SO.WEEKLY_HOLIDAY AND T.EMPLOYEE_NO = ATT_SO.EMPLOYEE_NO) AS RESULT_WH_SHIFT_TYPE_CODE ,TO_CHAR(ATT_SO.WORKING_DAY, 'DD/MM/YYYY') AS WORKING_DAY ,ATT_SO.WORKING_DAY_SHIFT_TYPE_CODE ,(SELECT T.SHIFT_TYPE_CODE FROM TB_ATT_RESULT_N T WHERE T.SUBSIDIARY_CODE = ATT_SO.SUBSIDIARY_CODE AND T.TIME_AND_ATTENDANCE_DATE = ATT_SO.WORKING_DAY AND T.EMPLOYEE_NO = ATT_SO.EMPLOYEE_NO) AS RESULT_NW_SHIFT_TYPE_CODE ,ATT_SO.TIME_ATTEND_INPUT_REASON_DESC ,ATT_SO.CREATION_USER_ID ,ATT_SO.CREATION_DATE ,ATT_SO.LAST_UPDATE_USER_ID ,ATT_SO.LAST_UPDATE_DATE FROM TB_ATT_SWAP_HOLIDAY_REQUEST_N ATT_SO LEFT OUTER JOIN EMP_MASTER EM ON (ATT_SO.EMPLOYEE_NO = EM.EMPLOYEE_NUMBER) WHERE 1=1 AND ATT_SO.SUBSIDIARY_CODE = #{subsidiaryCode}
AND ATT_SO.REQUEST_NO = #{requestNo}
AND ATT_SO.approval_request_id = #{requestMasterId} ORDER BY ATT_SO.REQUEST_SEQ_NO ASC

mapper.update:
	 MERGE /* LGVATT20551.saveSwapHolidayRequest */ INTO TB_ATT_SWAP_HOLIDAY_REQUEST_N ATT_SO
     USING DUAL
             ON (     
                  	  ATT_SO.REQUEST_CODE = #{requestCode}
                  AND ATT_SO.APPROVAL_REQUEST_ID = #{approvalRequestId}
                  AND ATT_SO.EMPLOYEE_NO = #{employeeNo}
                  AND ATT_SO.TIME_AND_ATTENDANCE_YYYYMM = TO_CHAR(TO_DATE(#{weeklyHoliday}, 'DD/MM/YYYY'), 'YYYYMM')
                )
       WHEN MATCHED THEN
            UPDATE SET                         
                    ATT_SO.SHIFT_TYPE_CODE                 = #{shiftTypeCode}
                    ,ATT_SO.WEEKLY_HOLIDAY                 = #{weeklyHoliday}
                    ,ATT_SO.WEEKLY_HOLIDAY_SHIFT_TYPE_CODE = #{weeklyHolidayShiftTypeCode}
                    ,ATT_SO.WORKING_DAY                    = #{workingDay}
                    ,ATT_SO.WORKING_DAY_SHIFT_TYPE_CODE    = #{workingDayShiftTypeCode}
                    ,CONFIRM_FLAG                          = 'Y'
                    ,PROGRESS_STATUS_CODE                  = (SELECT status_code FROM lgcom_approval_request_n WHERE request_master_id = ATT_SO.approval_request_id AND request_code = ATT_SO.request_code) 
                    ,LAST_UPDATE_USER_ID                   = #{sessionUserId}
                    ,LAST_UPDATE_DATE                      = SYSDATE
       WHEN NOT MATCHED THEN
            INSERT 
                   ( 
                    REQUEST_NO
                   ,REQUEST_SEQ_NO 
                   ,REQUEST_DATE
                   ,SUBSIDIARY_CODE
                   ,EMPLOYEE_NO
                   ,TIME_AND_ATTENDANCE_YYYYMM
                   ,SHIFT_TYPE_CODE
                   ,WEEKLY_HOLIDAY
                   ,WEEKLY_HOLIDAY_SHIFT_TYPE_CODE
                   ,WORKING_DAY
                   ,WORKING_DAY_SHIFT_TYPE_CODE
                   ,TIME_ATTEND_INPUT_REASON_DESC
                   ,APPROVAL_REQUEST_ID
                   ,REQUEST_CODE
                   ,PROGRESS_STATUS_CODE
                   ,CONFIRM_FLAG                   
                   ,CREATION_USER_ID
                   ,CREATION_DATE
                   ,LAST_UPDATE_USER_ID
                   ,LAST_UPDATE_DATE
                    )VALUES(
                    #{requestNo}
                   ,sq_tb_att_swap_holiday.NEXTVAL
                   ,SYSDATE
                   ,#{subsidiaryCode} 
                   ,#{employeeNo}
                   ,#{timeAndAttendanceYyyymm}
                   ,#{shiftTypeCode}
                   ,TO_DATE(#{weeklyHoliday}, 'DD/MM/YYYY')
                   ,#{weeklyHolidayShiftTypeCode}
                   ,TO_DATE(#{workingDay}, 'DD/MM/YYYY')
                   ,#{workingDayShiftTypeCode}
                   ,#{timeAttendInputReasonDesc}
                   ,#{approvalRequestId}
                   ,#{requestCode}
                   ,'20'
                   ,'N'                     
                   ,#{sessionUserId}
                   ,SYSDATE
                   ,#{sessionUserId}
                   ,SYSDATE
                       )

	UPDATE TB_ATT_SWAP_HOLIDAY_REQUEST_N ATT_SO
	   SET ATT_SO.PROGRESS_STATUS_CODE		= (SELECT status_code FROM lgcom_approval_request_n WHERE request_master_id = ATT_SO.approval_request_id AND request_code = ATT_SO.request_code) 
          ,ATT_SO.LAST_UPDATE_USER_ID      = #{sessionUserId}
          ,ATT_SO.LAST_UPDATE_DATE         = SYSDATE
	 WHERE ATT_SO.SUBSIDIARY_CODE 			= #{LGVHR_PROJECT_SESSION.subsidiaryCode} 
	   AND ATT_SO.REQUEST_CODE 			= #{requestCode}
       AND ATT_SO.APPROVAL_REQUEST_ID 		= #{approvalRequestId}

		UPDATE TB_ATT_SWAP_HOLIDAY_REQUEST_N


           SET progress_status_code = '30'


           SET progress_status_code = '40'


           SET progress_status_code = '50'


           SET progress_status_code = '70'


           SET progress_status_code = '20'


		      ,last_update_user_id  = #{sessionAppUserId}
		      ,last_update_date     = SYSDATE
		 WHERE approval_request_id = #{requestMasterId}
		 AND request_code = #{requestCode}
		 AND subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode}

DELETE FROM TB_ATT_SWAP_HOLIDAY_REQUEST_N ATT_SO
 WHERE ATT_SO.SUBSIDIARY_CODE = #{subsidiaryCode} 
   AND ATT_SO.TIME_AND_ATTENDANCE_DATE = TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY') 
   AND ATT_SO.EMPLOYEE_NO = #{employeeNo}

mapper.select:

		    SELECT /* LGVATT20551.checkAttendanceDate */
		       COUNT(*) AS count
			FROM (select subsidiary_code, time_and_attendance_date, employee_no, TIME_AND_ATTENDANCE_CODE FROM tb_att_result_n 
                  union all
                  select subsidiary_code, time_and_attendance_date, employee_no, TIME_AND_ATTENDANCE_CODE FROM tb_att_plan_n) ta
			WHERE  1 = 1
			AND    ta.subsidiary_code = #{subsidiaryCode}
			AND    ta.time_and_attendance_date = TO_DATE(#{attendanceDate}, 'DD/MM/YYYY')
			AND    ta.employee_no = #{employeeNo}
			AND    ta.TIME_AND_ATTENDANCE_CODE = #{workCode}
